      }
    ]
  },
  "learning_request": {
    "needed": true,
    "gap": "仍缺少日期合规且可读的鱼类双体轨迹方法，尤其是方向相似度、短位移噪声处理和追随判据的验证方式。",
    "why_now": "若R07分析扩展到方向相似度，需要知道鱼类研究中这些指标的具体操作范围；现有可读跨物种材料仅为潜水鸭群描述。",
    "queries": [
      "2010年以前鱼类双体轨迹研究如何定义坐标运动方向相关、相对方位和追随滞后？",
      "鱼类轨迹研究如何处理低速或短位移样本中的方向角噪声？",
      "二维质心轨迹何种额外证据可将坐标方向相关解释为鱼体朝向或感觉引导行为？"
    ],
    "urls": [],
    "source_ids": [],
    "record_ids": [],
    "operations": []
  },
  "analysis_plan": {
    "kind": "analysis",
    "question": "在R07中比较记录内较近与较远距离状态之后10帧的距离变化，并描述A、B各自10帧位移大小。",
    "record_id": "R07",
    "start": 0,
    "stop": 44999,
    "variables": [
      {
        "name": "distance",
        "expression": "norm(positions[:,0,:]-positions[:,1,:],axis=-1)",
        "meaning": "A与B坐标间二维欧氏距离",
        "units": "原生图像坐标单位"
      },
      {
        "name": "change_10",
        "expression": "shift(distance,-10)-distance",
        "meaning": "10帧后距离减当前距离",
        "units": "原生图像坐标单位/10帧"
      },
      {
        "name": "A_displacement_10",
        "expression": "norm(shift(positions[:,0,:],-10)-positions[:,0,:],axis=-1)",
        "meaning": "A在10帧间隔上的位移大小",
        "units": "原生图像坐标单位/10帧"
      },
      {
        "name": "B_displacement_10",
        "expression": "norm(shift(positions[:,1,:],-10)-positions[:,1,:],axis=-1)",
        "meaning": "B在10帧间隔上的位移大小",
        "units": "原生图像坐标单位/10帧"
      },
      {
        "name": "valid_pair",
        "expression": "isfinite(distance)&isfinite(change_10)&isfinite(A_displacement_10)&isfinite(B_displacement_10)",
        "meaning": "当前与10帧后两标签坐标均有限",
        "units": "boolean"
      },
      {
        "name": "near_threshold",
        "expression": "quantile(distance,0.25)",
        "meaning": "R07全记录距离第25分位数",
        "units": "原生图像坐标单位"
      },
      {
        "name": "far_threshold",
        "expression": "quantile(distance,0.75)",
        "meaning": "R07全记录距离第75分位数",
        "units": "原生图像坐标单位"
      }
    ],
    "outputs": [
      {
        "name": "distance",
        "expression": "distance"
      },
      {
        "name": "future_distance_change",
        "expression": "change_10"
      },
      {
        "name": "individual_displacements",
        "expression": "A_displacement_10"
      }
    ],
    "groups": [
      {
        "name": "near",
        "where": "valid_pair&(distance<=near_threshold)",
        "values": ["distance", "change_10", "A_displacement_10", "B_displacement_10"]
      },
      {
        "name": "far",
        "where": "valid_pair&(distance>=far_threshold)",
        "values": ["distance", "change_10", "A_displacement_10", "B_displacement_10"]
      }
    ]
  },
  "memory_notes": [],
  "memory_use": [
    {
      "key": "trajectory_position_is_not_sensorimotor_state",
      "source_task": "fish_001/inquiry_v2_live_20261106_002",
      "used_for": "区分坐标位移方向与鱼体朝向、追随或感觉引导解释。",
      "scope_check": "适用于当前仅有二维追踪坐标、任务与姿态未核实的情境；该笔记不提供鱼类双体指标验证。"
    }
  ],
  "still_cannot_explain_or_use": "仍不能说明任何距离或方向统计是否由社会互动、感觉输入、共同环境或追踪误差造成；也不能把位置差分解释为鱼体朝向。",
  "evidence_claims": [
    {
      "id": "coordinate_heading_distinction",
      "text": "由二维坐标差分得到的位移方向表示质心在图像平面中的运动方向；没有鱼体姿态时，它不表示鱼头朝向或感觉运动中的定向反应。",
      "kind": "inference",
      "use": "research_decision",
      "consequence": "若报告两标签方向相似度，应称为坐标位移方向相似度，不称为朝向一致、追随或感觉引导。",
      "basis": {
        "source_ids": ["K7f402d28a9ddd743"],
        "record_ids": ["R07"]
      },
      "depends_on": ["01_initial_1_learn_2:c1"]
    },
    {
      "id": "distance_and_direction_are_distinct",
      "text": "两标签距离变化与其位移方向相似度是不同的轨迹描述量；距离缩小本身不能推出两条轨迹同向运动。",
      "kind": "inference",
      "use": "research_decision",
      "consequence": "近远状态后的距离变化作为主要结果；方向相似度若计算则单独列为次要描述，不以其替代距离转移。",
      "basis": {
        "source_ids": [],
        "record_ids": ["R07"]
      },
      "depends_on": ["r1_exchange_0:pair_distance_is_motion_ambiguous"]
    }
  ],
  "doubts": [
    {
      "claim_ref": "coordinate_heading_distinction",
      "type": "unproved_hypothesis",
      "reason": "本轮未取得当前鱼体姿态数据；该区分是变量可识别范围的判断，不是R07计算结果。",
      "consequence": "只把坐标方向相似度作为可选轨迹描述，不将其用于推断鱼体朝向或感觉引导。"
    }
  ]
}
